        html = std::regex_replace(html, match, "<h" + header_level + ">" + header_text + "</h" + header_level + ">");
        html = std::regex_replace(html, std::regex("^#{1,6}", std::regex::match_flag_type::match_not_null), "");
    }

    return html;
}

int main() {
    std::string markdown = "Hello, _world_! This is a **bold** and *italic* text. [Link](https://example.com) to an external site. # Header 1\n## Header 2\n### Header 3\n#### Header 4\n##### Header 5\n###### Header 6";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

